  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --panel: rgba(255, 255, 255, 0.9);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #0f172a;
      --muted: #475569;
      --primary: #4f46e5;
      --primary-soft: rgba(79, 70, 229, 0.12);
      --ring: rgba(79, 70, 229, 0.2);
      --shadow: 0 24px 60px rgba(15, 23, 42, 0.14);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(99, 102, 241, 0.18), transparent 32%),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 30%),
        var(--bg);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 20px;
    }

    .app-shell {
      width: min(100%, 720px);
    }

    .card {
      background: var(--panel);
      border: 1px solid var(--panel-border);
      border-radius: 28px;
      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
      overflow: hidden;
    }

    .card-content {
      padding: 40px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 999px;
      background: var(--primary-soft);
      color: var(--primary);
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    h1 {
      margin: 20px 0 10px;
      font-size: clamp(2rem, 4vw, 2.8rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .intro {
      margin: 0 0 28px;
      max-width: 56ch;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.7;
    }

    form {
      display: grid;
      gap: 24px;
    }

    .form-field {
      display: grid;
      gap: 18px;
      padding: 24px;
      border: 1px solid rgba(148, 163, 184, 0.2);
      border-radius: 22px;
      background: rgba(248, 250, 252, 0.84);
    }

    .field-label {
      margin: 0;
      font-size: 1.1rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .field-help {
      margin: -8px 0 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .radio-group {
      display: grid;
      gap: 14px;
    }

    .radio-option {
      position: relative;
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 16px 18px;
      border: 1px solid rgba(148, 163, 184, 0.28);
      border-radius: 18px;
      background: #fff;
      transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
      cursor: pointer;
    }

    .radio-option:hover {
      border-color: rgba(79, 70, 229, 0.4);
      transform: translateY(-1px);
      box-shadow: 0 14px 28px rgba(15, 23, 42, 0.08);
    }

    .radio-option:focus-within {
      border-color: var(--primary);
      box-shadow: 0 0 0 4px var(--ring);
    }

    .radio-option input[type="radio"] {
      width: 20px;
      height: 20px;
      margin: 0;
      accent-color: var(--primary);
      flex: 0 0 auto;
    }

    .option-copy {
      display: grid;
      gap: 4px;
    }

    .option-title {
      font-weight: 700;
      font-size: 1rem;
    }

    .option-description {
      color: var(--muted);
      font-size: 0.92rem;
      line-height: 1.45;
    }

    .form-actions {
      display: flex;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
    }

    .submit-button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      background: linear-gradient(135deg, #4338ca, #6366f1);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 16px 30px rgba(79, 70, 229, 0.28);
      transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
    }

    .submit-button:hover {
      transform: translateY(-1px);
      box-shadow: 0 18px 34px rgba(79, 70, 229, 0.32);
    }

    .submit-button:active {
      transform: translateY(0);
    }

    .status-message {
      min-height: 1.5em;
      color: var(--muted);
      font-size: 0.95rem;
    }

    @media (max-width: 640px) {
      .card-content {
        padding: 28px 20px;
      }

      .form-field {
        padding: 20px;
      }
    }
  </style>
</head>
<body>
  <div id="root"></div>
  <script>
    const notificationOptions = [
      {
        value: "Email",
        title: "Email",
        description: "Get updates in your inbox with full details and easy record-keeping."
      },
      {
        value: "SMS",
        title: "SMS",
        description: "Receive quick text alerts for timely reminders and important changes."
      },
      {
        value: "Push Notifications",
        title: "Push Notifications",
        description: "Stay in the loop instantly with real-time notifications on your device."
      }
    ];

    function RadioOption({ name, option }) {
      return `
        <label class="radio-option">
          <input type="radio" name="${name}" value="${option.value}" required>
          <span class="option-copy">
            <span class="option-title">${option.title}</span>
            <span class="option-description">${option.description}</span>
          </span>
        </label>
      `;
    }

    function FormField() {
      return `
        <div class="form-field">
          <p class="field-label">How do you prefer to receive notifications?</p>
          <p class="field-help">Choose one option to set your preferred notification channel.</p>
          <div class="radio-group" role="radiogroup" aria-labelledby="notification-question">
            ${notificationOptions.map((option) => RadioOption({ name: "notificationPreference", option })).join("")}
          </div>
        </div>
      `;
    }

    function NotificationForm() {
      return `
        <form id="notification-form">
          ${FormField()}
          <div class="form-actions">
            <button class="submit-button" type="submit">Submit</button>
            <div class="status-message" id="status-message" aria-live="polite"></div>
          </div>
        </form>
      `;
    }

    function App() {
      return `
        <main class="app-shell">
          <section class="card">
            <div class="card-content">
              <span class="eyebrow">Preferences</span>
              <h1>Choose your preferred notifications</h1>
              <p class="intro">Set how you’d like us to contact you so product updates and reminders arrive in the channel that fits you best.</p>
              ${NotificationForm()}
            </div>
          </section>
        </main>
      `;
    }

    document.getElementById("root").innerHTML = App();

    const form = document.getElementById("notification-form");
    const statusMessage = document.getElementById("status-message");
    const questionLabel = document.querySelector(".field-label");

    questionLabel.id = "notification-question";

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const selected = new FormData(form).get("notificationPreference");
      statusMessage.textContent = selected
        ? `Preference saved: ${selected}.`
        : "Please select a notification method before submitting.";
    });
  </script>
</body>
</html>
